Object name = authentication.getPrincipal();
Object secret = authentication.getCredentials();
if (name == null || secret == null) {
    return Mono.empty();
}
return users.findByUsername(name.toString())
        .filter(user -> user.isEnabled() && user.isAccountNonLocked() && user.isAccountNonExpired()
                && user.isCredentialsNonExpired())
        .filter(user -> encoder.matches(secret.toString(), user.getPassword()))
        .<Authentication>map(user -> UsernamePasswordAuthenticationToken.authenticated(
                user.getUsername(), null, user.getAuthorities()))
        .onErrorResume(error -> Mono.empty());

